// The emitter: one merged OpenAPI document in, the generated files out
// (`models.ts`, one module per tag, `services.ts`, `index.ts`) as a
// name → source map. Nothing here touches the disk or the network.
import { upgradeDocument } from "./load/upgrade.js";
import { emitZod } from "./emit-zod.js";
import type {
  EmitResult,
  ForgeOptions,
  HttpMethod,
  Loose,
  MediaType,
  OpenApiDocument,
  OperationInfo,
  OperationObject,
  Parameter,
  Problem,
  Schema,
} from "./types.js";
import { shareIdenticalTypes } from "./shared-types.js";
import { LIBRARIES } from "./runtime/libraries/index.js";
import {
  camelCase,
  identifier,
  modelName,
  oneLine,
  pascalCase,
  propertyName,
  upperFirst,
} from "./names.js";

/** Types the emitted code uses by name, which a schema must not take over. */
const GLOBAL_TYPES = new Set([
  "Array",
  "Blob",
  "Boolean",
  "Date",
  "Error",
  "File",
  "FormData",
  "Function",
  "Map",
  "Number",
  "Object",
  "Omit",
  "Partial",
  "Promise",
  "Readonly",
  "Record",
  "Required",
  "Set",
  "String",
  "Symbol",
]);

const HTTP_METHODS: HttpMethod[] = ["get", "put", "post", "patch", "delete"];

/** Header parameters OpenAPI says to ignore: the transport owns them. */
const IGNORED_HEADERS = new Set(["accept", "content-type", "authorization"]);

/**
 * @param {object} spec     the (merged) OpenAPI document
 * @param {object} options  resolved options — see config.mjs
 * @param {string} source   what the banner says the files were made from
 */
export function emit(
  inputSpec: OpenApiDocument,
  options: ForgeOptions,
  source: string,
): EmitResult {
  const rt = options.runtime;
  const { list, envelope } = rt;
  const { infinite } = options;
  const hooks = options.target === "hooks";
  const { prefix } = LIBRARIES[options.library];
  // A reactive library reads its arguments where the request is made, so a
  // ref, a signal or a getter in their place keeps the query in step.
  const reactive = hooks && LIBRARIES[options.library].reactive;
  const generator = options.generatorName;
  const banner = `/* This file is auto-generated by ${generator}`;
  const bannerFrom = `${banner} from ${source}. Do not edit manually. */`;
  const bannerPlain = `${banner}. Do not edit manually. */`;
  const apiPrefix = options.apiPrefix;
  const include = options.tags.include;
  const exclude = options.tags.exclude;
  const envelopeKeys = envelope ? new Set(envelope.keys) : new Set();

  let spec = inputSpec;

  const registry = () => spec.components?.schemas ?? {};

  // Where the type being rendered comes from, and what the document leaves
  // out there. The output stays valid (`unknown`); the problems are reported.
  const SCHEMA_REF = "#/components/schemas/";
  const inlining = new Set<string>();
  const problems = new Map<string, Problem>();
  let where: string | null = null;
  const note = (message: string) => {
    if (where) problems.set(`${where}: ${message}`, { where, message });
  };

  function refTarget(ref: string): Schema | undefined {
    let node: Loose = spec;
    for (const part of String(ref).replace(/^#\//, "").split("/")) {
      node = node?.[part.replace(/~1/g, "/").replace(/~0/g, "~")];
    }
    return node;
  }

  function deref(node: Schema | undefined, seen = new Set<string>()): Schema {
    if (!node?.$ref) return node ?? {};
    if (seen.has(node.$ref)) return { type: "object" };
    seen.add(node.$ref);
    return deref(refTarget(node.$ref) ?? {}, seen);
  }

  /** Inline object schemas are emitted once in `models.ts` and named after. */
  const extraModels = new Map<string, string | null>();

  function typeFor(
    schema: Schema | boolean | null | undefined,
    fallbackName: string,
  ): string {
    // JSON Schema's `true`: any value, said on purpose (`additionalProperties: true`).
    if (schema === true) return "unknown";
    if (!schema || typeof schema !== "object") {
      note("has no schema, so it is typed `unknown`");
      return "unknown";
    }
    if (schema.$ref && refTarget(schema.$ref) === undefined) {
      note(
        `refers to ${schema.$ref}, which does not exist, so it is typed \`unknown\``,
      );
      return "unknown";
    }
    if (schema.$ref && !String(schema.$ref).startsWith(SCHEMA_REF)) {
      // A pointer into `paths` or another corner: it has no name to refer to.
      const seen = inlining.has(schema.$ref);
      if (seen) return "unknown";
      inlining.add(schema.$ref);
      const text = typeFor(refTarget(schema.$ref), fallbackName);
      inlining.delete(schema.$ref);
      return text;
    }
    const text = schema.$ref
      ? modelName(schema.$ref)
      : renderType(schema, fallbackName);
    if (schema.nullable !== true || text === "unknown" || text === "null") {
      return text;
    }
    return /[|&\s]/.test(text) ? `(${text}) | null` : `${text} | null`;
  }

  function renderType(schema: Schema, fallbackName: string): string {
    if (schema.oneOf?.length)
      return joinTypes(schema.oneOf, fallbackName, "Option");
    if (schema.anyOf?.length)
      return joinTypes(schema.anyOf, fallbackName, "Variant");
    if (schema.allOf?.length) {
      return joinTypeTexts(
        schema.allOf.map((part, index) =>
          typeFor(part, `${fallbackName}Part${index}`),
        ),
        " & ",
      );
    }
    if (schema.enum) {
      return schema.enum
        .map((value) =>
          typeof value === "string" ? JSON.stringify(value) : String(value),
        )
        .join(" | ");
    }

    const resolved = schema.$ref ? deref(schema, new Set()) : schema;

    switch (
      Array.isArray(resolved.type) ? resolved.type.join("|") : resolved.type
    ) {
      case undefined: {
        if (resolved.type === "null") return "null";
        if (resolved.properties) return objectLiteral(resolved, fallbackName);
        if (resolved.additionalProperties) {
          return `Record<string, ${typeFor(resolved.additionalProperties, `${fallbackName}Value`)}>`;
        }
        note("declares no type, so it is typed `unknown`");
        return "unknown";
      }
      case "null":
        return "null";
      case "string":
        // An uploaded file (`multipart/form-data`) is sent as one, not as text.
        return resolved.format === "binary" ? "Blob" : "string";
      case "integer":
      case "number":
        return "number";
      case "boolean":
        return "boolean";
      case "array": {
        // A fixed-length list (OpenAPI 3.1 `prefixItems`) is a tuple.
        if (resolved.prefixItems?.length) {
          return `[${resolved.prefixItems.map((part, index) => typeFor(part, `${fallbackName}Item${index}`)).join(", ")}]`;
        }
        const item = typeFor(resolved.items, `${fallbackName}Item`);
        return /[|&\s]/.test(item) ? `(${item})[]` : `${item}[]`;
      }
      case "object":
        return objectLiteral(resolved, fallbackName);
      default:
        note(
          `has the unsupported type \`${resolved.type}\`, so it is typed \`unknown\``,
        );
        return "unknown";
    }
  }

  function joinTypes(
    nodes: Schema[],
    fallbackName: string,
    label: string,
  ): string {
    return joinTypeTexts(
      nodes.map((node, index) =>
        typeFor(node, `${fallbackName}${label}${index}`),
      ),
      " | ",
    );
  }

  function joinTypeTexts(parts: string[], separator = " | ") {
    const clean = parts.filter(Boolean);
    if (!clean.length) return "unknown";
    if (separator === " & ") {
      // `X & unknown` is `X`: an empty `allOf` part adds nothing.
      const meaningful = clean.filter((part) => part !== "unknown");
      if (!meaningful.length) return "unknown";
      if (meaningful.length === 1) return meaningful[0];
      return meaningful.map((part) => `(${part})`).join(" & ");
    }
    if (clean.length === 1) return clean[0];
    return clean.join(" | ");
  }

  /**
   * The name an inline object is emitted under. A schema keeps its name, and a
   * second, different object that would take a name already held (by another
   * inline object, or by a component of that name) gets a numeric suffix.
   */
  const inlineOwners = new Map();
  function claimName(schema: Schema, name: string) {
    for (let candidate = name, i = 2; ; candidate = `${name}${i++}`) {
      const owner = inlineOwners.get(candidate);
      if (owner === schema) return candidate;
      if (
        owner === undefined &&
        (!(candidate in registry()) || registry()[candidate] === schema)
      ) {
        inlineOwners.set(candidate, schema);
        return candidate;
      }
    }
  }

  function objectLiteral(schema: Schema, requestedName: string): string {
    const properties = schema.properties ?? {};
    const names = Object.keys(properties);
    if (!names.length) {
      return schema.additionalProperties
        ? `Record<string, ${typeFor(schema.additionalProperties, `${requestedName}Value`)}>`
        : "Record<string, unknown>";
    }

    const fallbackName = claimName(schema, requestedName);
    if (extraModels.has(fallbackName)) return fallbackName;
    extraModels.set(fallbackName, null); // claimed first, so a cycle terminates

    const required = new Set(schema.required ?? []);
    const lines = names.map((name) => {
      const child = properties[name] ?? {};
      const type = typeFor(child, `${fallbackName}${pascalCase(name)}`);
      const comment = child.description
        ? `  /** ${oneLine(child.description)} */\n`
        : "";
      return `${comment}  ${propertyName(name)}${required.has(name) ? "" : "?"}: ${type};`;
    });

    // The body alone: the model loop wraps it in the declaration and can then
    // apply a `nullable` schema to the whole type.
    extraModels.set(fallbackName, `{\n${lines.join("\n")}\n}`);
    return fallbackName;
  }

  /**
   * `$ref`s used inside `components` — the places where a named type is needed
   * by the emitted models, not unwrapped away with its response.
   */
  function collectComponentRefs() {
    const refs = new Set();
    const walk = (node: Loose) => {
      if (Array.isArray(node)) {
        for (const item of node) walk(item);
        return;
      }
      if (node && typeof node === "object") {
        for (const [key, value] of Object.entries(node)) {
          if (key === "$ref" && typeof value === "string") refs.add(value);
          else walk(value);
        }
      }
    };
    walk(spec.components ?? {});
    return refs;
  }

  /** The envelope's own fields and nothing else — the transport unwraps it. */
  function isEnvelopeWrapper(schema: Schema) {
    if (!envelope) return false;
    const names = Object.keys(schema?.properties ?? {});
    return (
      names.length > 0 &&
      names.includes(envelope.result) &&
      names.every((name) => envelopeKeys.has(name))
    );
  }

  /**
   * An envelope expressed as `allOf: [EnvelopeBase, { data: T }]` — the
   * generic envelope type already describes it, so the per-endpoint narrowing
   * is noise. Returns the data type text when the schema matches, else `null`.
   */
  function envelopeDataPayload(schema: Schema, name: string) {
    if (!envelope) return null;
    if (!schema?.allOf?.length || schema.allOf.length !== 2) return null;

    const [base, narrowing] = schema.allOf;
    const baseTarget = base?.$ref ? refTarget(base.$ref) : base;
    if (!baseTarget || !isEnvelopeWrapper(baseTarget)) return null;

    const narrowProps = narrowing?.properties ?? {};
    if (!(envelope.data in narrowProps)) return null;

    return typeFor(narrowProps[envelope.data], `${name}Data`);
  }

  const resolveParameter = (item: Parameter): Parameter =>
    item.$ref ? (deref(item as Schema) as Parameter) : item;

  function collectOperations(): OperationInfo[] {
    const operations = [];
    const taken = new Set();

    for (const [path, pathItem] of Object.entries(spec.paths ?? {})) {
      if (!pathItem || typeof pathItem !== "object") continue;

      const shared = (pathItem.parameters ?? []).map(resolveParameter);

      for (const method of HTTP_METHODS) {
        const operation: OperationObject | undefined = pathItem[method];
        if (!operation) continue;

        const own = (operation.parameters ?? []).map(resolveParameter);
        const byKey = new Map();
        for (const parameter of [...shared, ...own]) {
          if (parameter?.name) {
            byKey.set(`${parameter.in}:${parameter.name}`, parameter);
          }
        }
        const parameters = [...byKey.values()];

        const base = identifier(
          operation.operationId ?? `${method} ${path}`,
          `${method}Path${operations.length}`,
        );
        // A name already in use gets the method (`getUserGet`), then a number.
        let name = base;
        for (let i = 1; taken.has(name); i += 1) {
          name = `${base}${upperFirst(method)}${i > 1 ? i : ""}`;
        }
        taken.add(name);

        const content: Record<string, MediaType> =
          operation.requestBody?.content ?? {};
        // JSON when the document offers it, else the first body with a schema.
        const bodyEntry =
          Object.entries(content).find(([type]) => type === "application/json") ??
          Object.entries(content).find(
            ([type, item]) => type.includes("json") && item?.schema,
          ) ??
          Object.entries(content).find(([, item]) => item?.schema);
        const requestMedia = bodyEntry?.[1] ?? null;
        // The HTTP client sends no body with GET or DELETE, so a body on one
        // is left out of the signature instead of being silently dropped.
        const at = `${method.toUpperCase()} ${path}`;
        if (method === "delete" && operation.requestBody && !rt.requestKeys.body) {
          problems.set(`${at}: skipped`, {
            where: at,
            message:
              "was skipped: it takes a request body, which the client cannot send with DELETE (`runtime.requestKeys.body`)",
          });
          continue;
        }
        const sendsBody = !(method === "get" && operation.requestBody);
        if (!sendsBody) {
          problems.set(`${at}: body`, {
            where: at,
            message:
              "declares a request body, which cannot be sent with GET; it is left out",
          });
        }
        for (const item of parameters) {
          const ignored =
            item.in === "header" && IGNORED_HEADERS.has(item.name.toLowerCase());
          const gap =
            item.in === "cookie"
              ? "is a cookie, which the client cannot send: a browser attaches cookies itself"
              : item.in === "header" && !ignored && !rt.requestKeys.headers
                ? "is a header, which the custom client takes none of (`runtime.requestKeys.headers`)"
                : null;
          if (gap) {
            const spot = `${at} parameter \`${item.name}\``;
            problems.set(`${spot}: ${gap}`, { where: spot, message: gap });
          }
        }
        const success: { content?: Record<string, MediaType> } =
          Object.entries(operation.responses ?? {}).find(([status]) =>
            /^2\d\d$/.test(status),
          )?.[1] ?? {};
        const successContent =
          success.content?.["application/json"] ??
          success.content?.["application/*+json"] ??
          Object.values(success.content ?? {}).find((item) => item?.schema) ??
          null;

        let built: OperationInfo = {
          name,
          method,
          path,
          // The base URL already carries the prefix, so the route does not.
          url:
            (apiPrefix && path.startsWith(apiPrefix)
              ? path.slice(apiPrefix.length)
              : path) || "/",
          tags: operation.tags?.length ? operation.tags : ["default"],
          summary: operation.summary,
          description: operation.description,
          deprecated: operation.deprecated === true,
          pathParams: parameters.filter((item) => item.in === "path"),
          queryParams: parameters
            .filter((item) => item.in === "query")
            .map((item) => ({
              ...item,
              name:
                options.transform.queryParam?.(item.name, {
                  service: operation["x-service"] ?? null,
                  operation: name,
                  path,
                }) ?? item.name,
            })),
          headerParams: rt.requestKeys.headers
            ? parameters.filter(
                (item) => item.in === "header" && !IGNORED_HEADERS.has(item.name.toLowerCase()),
              )
            : [],
          bodySchema: sendsBody ? (requestMedia?.schema ?? null) : null,
          bodyRequired: sendsBody && operation.requestBody?.required === true,
          bodyMediaType: sendsBody && requestMedia?.schema ? bodyEntry![0] : null,
          responseSchema: successContent?.schema ?? null,
          service: operation["x-service"] ?? null,
        };

        const renamed = options.transform.operationName?.(built);
        if (renamed) {
          built = { ...built, name: identifier(renamed, built.name) };
        }
        if (options.transform.operation) {
          const changed = options.transform.operation(built);
          if (!changed) continue;
          built = changed;
        }
        operations.push(built);
      }
    }

    return operations;
  }

  /**
   * The properties of an operation's answer. An envelope may be split across
   * an `allOf` (a base with `result`, `code`, `message` and `data`, plus a
   * per-operation part narrowing `data`), so the fields are merged before
   * deciding that the answer is one.
   */
  function answerShape(operation: OperationInfo) {
    const declared = operation.responseSchema;
    if (!declared) return null;
    const node = declared.$ref ? refTarget(declared.$ref) : declared;
    const props: Record<string, Schema> = node?.allOf?.length
      ? node.allOf.reduce(
          (merged, part) => ({
            ...merged,
            ...((part.$ref ? refTarget(part.$ref) : part)?.properties ?? {}),
          }),
          {},
        )
      : (node?.properties ?? {});
    const wraps = Boolean(
      envelope && props[envelope.result] && props[envelope.data],
    );
    return { declared, props, wraps };
  }

  /** The answer is an envelope: the client unwraps it, and only for a call that says so. */
  const wrapsEnvelope = (operation: OperationInfo) =>
    answerShape(operation)?.wraps ?? false;

  /**
   * A `{ count, list }` payload is the list type only when the document says
   * both fields are always there; with either one optional the payload keeps
   * its own, honest type.
   */
  function isListShape(data: Schema): data is Schema & { properties: Record<string, Schema> } {
    if (!list || !data.properties) return false;
    const required = new Set(data.required ?? []);
    const count = deref(data.properties[list.count]);
    const items = data.properties[list.items];
    return (
      (list.assumeRequired ||
        (required.has(list.count) && required.has(list.items))) &&
      (count.type === "integer" || count.type === "number") &&
      count.nullable !== true &&
      (items?.type === "array" || Boolean(items?.items)) &&
      items?.nullable !== true
    );
  }

  /** The payload type is the envelope's `data`; `{ count, list }` is the list type. */
  function payloadFor(operation: OperationInfo) {
    const shape = answerShape(operation);
    if (!shape) return "null";
    const { declared, props, wraps } = shape;
    const data = wraps && envelope ? props[envelope.data] : declared;

    if (!data) return "null";
    if (
      data.nullable === true &&
      !data.$ref &&
      !data.type &&
      !data.properties
    ) {
      return "null";
    }

    const resolved = deref(data, new Set());
    if (list && isListShape(resolved)) {
      const items = resolved.properties[list.items];
      return `${list.name}<${typeFor(items.items, `${pascalCase(operation.name)}Item`)}>`;
    }

    return typeFor(data, `${pascalCase(operation.name)}Response`);
  }

  const pathArgNames = (operation: OperationInfo) =>
    operation.pathParams.map((item) =>
      identifier(item.name, `${operation.name}Path`),
    );

  const paramType = (parameter: Parameter) =>
    typeFor(parameter.schema, pascalCase(`${parameter.name}Param`));

  /**
   * The client writes a list as repeated keys (`a=1&a=2`) and an object as
   * `a[b]=1`. A query parameter that asks for another style is reported, not
   * silently sent differently.
   */
  function checkQueryEncoding(parameter: Parameter) {
    const schema = deref(parameter.schema);
    if (
      schema.type === "array" &&
      (parameter.explode === false ||
        parameter.style === "spaceDelimited" ||
        parameter.style === "pipeDelimited")
    ) {
      note(
        `is a list the document writes on one line, but the client repeats the key (\`${parameter.name}=a&${parameter.name}=b\`)`,
      );
    }
    if (
      (schema.type === "object" || (!schema.type && schema.properties)) &&
      parameter.style !== "deepObject"
    ) {
      note(
        `is an object, which the client writes as \`${parameter.name}[property]=value\` (deepObject)`,
      );
    }
  }

  const queryTypeName = (operation: OperationInfo) => `${pascalCase(operation.name)}Query`;
  /** A `= {}` default is only legal while every query parameter is optional. */
  const queryIsOptional = (operation: OperationInfo) =>
    !operation.queryParams.some((item) => item.required);
  const headersTypeName = (operation: OperationInfo) => `${pascalCase(operation.name)}Headers`;
  /** Likewise: a `= {}` default only while no header is required. */
  const headersAreOptional = (operation: OperationInfo) =>
    !operation.headerParams.some((item) => item.required);
  const variablesTypeName = (operation: OperationInfo) =>
    `${pascalCase(operation.name)}Variables`;
  const bodyTypeName = (operation: OperationInfo) =>
    typeFor(operation.bodySchema, `${pascalCase(operation.name)}Body`);

  /**
   * A header is text on the wire. When every declared header is already a
   * string they are spread as they are; otherwise (a number, a flag, a list)
   * the values are written with `String()` here, so a transport that types
   * its headers `Record<string, string>` takes them as they are.
   */
  function headerSpread(operation: OperationInfo) {
    const isText = (type: string) =>
      /^(string|"[^"]*"(\s\|\s"[^"]*")*)$/.test(type);
    if (operation.headerParams.every((item) => isText(paramType(item)))) {
      return "...headers";
    }
    return [
      "...Object.fromEntries(",
      "      Object.entries(headers)",
      "        .filter(([, value]) => value !== undefined)",
      "        .map(([name, value]) => [name, String(value)]),",
      "    )",
    ].join("\n");
  }

  /** How a body goes out, by the media type the document gives it. */
  function bodyKind(media: string | null) {
    if (!media || media.includes("json")) return "json";
    if (media.startsWith("multipart/")) return "multipart";
    if (media.startsWith("application/x-www-form-urlencoded")) return "urlencoded";
    return "raw";
  }

  /**
   * How emitted code reads a route back out of its tag's `Endpoints` map: the
   * operation's own key there, so the URL itself is written once — in the map —
   * and the request function and the query key both point at it.
   */
  function endpointRef(endpoints: string, operation: OperationInfo) {
    const name = propertyName(operation.name);
    return name === operation.name
      ? `${endpoints}.${name}`
      : `${endpoints}[${name}]`;
  }

  /** A hook argument's declared type, and how it is read, in a reactive library. */
  const argType = (type: string) =>
    reactive ? `${rt.types.maybeGetter}<${type}>` : type;
  const argRead = (name: string) =>
    reactive ? `${rt.hooks.toValue}(${name})` : name;
  const lazy = (expression: string) =>
    reactive ? `() => ${expression}` : expression;

  /**
   * A read is an infinite list when it answers the paged shape and takes both
   * paging parameters; the query it is given is the rest of its parameters.
   */
  function infiniteOf(operation: OperationInfo) {
    if (!hooks || !infinite || !list || operation.method !== "get")
      return null;
    // A path id makes it a detail read, not a list.
    if (operation.pathParams.length) return null;
    const payload = payloadFor(operation);
    if (!payload.startsWith(`${list.name}<`)) return null;
    const names = operation.queryParams.map((item) => item.name);
    if (!names.includes(infinite.start) || !names.includes(infinite.size))
      return null;
    const rest = operation.queryParams.filter(
      (item) => item.name !== infinite.start && item.name !== infinite.size,
    );
    return {
      item: payload.slice(list.name.length + 1, -1),
      rest,
      omit: `Omit<${queryTypeName(operation)}, ${JSON.stringify(infinite.start)} | ${JSON.stringify(infinite.size)}>`,
      optional: !rest.some((item) => item.required),
      headers: operation.headerParams.length ? headersTypeName(operation) : null,
    };
  }

  const infiniteKey = (operation: OperationInfo) => `${operation.name}Infinite`;

  function infiniteKeyEntry(operation: OperationInfo, keys: string, endpoints: string) {
    const { omit, headers } = infiniteOf(operation)!;
    return [
      `  ${infiniteKey(operation)}: (params: ${omit}${headers ? `, headers: ${headers}` : ""}) =>`,
      `    [...${keys}.lists(), ${endpointRef(endpoints, operation)}, "infinite", params${headers ? ", headers" : ""}] as const,`,
    ].join("\n");
  }

  function infiniteHookBlock(operation: OperationInfo, keys: string) {
    const { item, omit, optional, headers } = infiniteOf(operation)!;
    const { start, size } = infinite as { start: string; size: string };
    const signal = rt.requestKeys.signal;
    return [
      requestDoc(operation),
      `export function ${prefix}${pascalCase(operation.name)}InfiniteQuery(`,
      `  query: ${argType(omit)}${optional ? " = {}" : ""},`,
      ...(headers
        ? [`  headers: ${argType(headers)}${headersAreOptional(operation) ? " = {}" : ""},`]
        : []),
      `  options?: ${rt.types.infinite}<${item}, ReturnType<typeof ${keys}.${infiniteKey(operation)}>>,`,
      `) {`,
      `  return ${rt.hooks.infinite}(`,
      `    ${lazy(`${keys}.${infiniteKey(operation)}(${argRead("query")}${headers ? `, ${argRead("headers")}` : ""})`)},`,
      `    (page, signal) =>`,
      `      ${operation.name}({ ...${argRead("query")}, ${propertyName(start)}: page.start, ${propertyName(size)}: page.size }, ${headers ? `${argRead("headers")}, ` : ""}{ ${signal === "signal" ? "signal" : `${signal}: signal`} }),`,
      `    options,`,
      `  );`,
      `}`,
    ].join("\n");
  }

  function tagModule(tag: string, operations: OperationInfo[]) {
    const name = identifier(tag, "api");
    const keys = `${name}Keys`;
    const endpoints = `${name}Endpoints`;
    const reads = operations.filter((operation) => operation.method === "get");
    const writes = operations.filter((operation) => operation.method !== "get");

    const chunks = [
      [
        `/**`,
        ` * The routes of "${tag}" — the one place each URL is written. The`,
        ` * request functions read their route from here${hooks ? ", and so do the keys," : ","}`,
        ` * so a path moves in a single line.`,
        ` */`,
        `export const ${endpoints} = {`,
        ...operations.map(
          (operation) =>
            `  ${propertyName(operation.name)}: ${JSON.stringify(operation.url)},`,
        ),
        "} as const;",
      ].join("\n"),
      hooks ? keyFactoryBlock(tag, operations, keys, endpoints) : "",
      shareIdenticalTypes(
        [
          ...operations.flatMap((operation) => [
            queryTypeBlock(operation),
            headersTypeBlock(operation),
          ]),
          ...writes.map((operation) => variablesBlock(operation)),
        ].filter(Boolean),
        undefined,
        true,
      ).join("\n\n"),
      operations
        .map((operation) => requestBlock(operation, endpoints))
        .join("\n\n"),
      hooks
        ? reads
            .flatMap((operation) => [
              queryHookBlock(operation, keys),
              infiniteOf(operation) ? infiniteHookBlock(operation, keys) : null,
            ])
            .filter(Boolean)
            .join("\n\n")
        : "",
      hooks
        ? writes
            .map((operation) => mutationHookBlock(operation, keys))
            .join("\n\n")
        : "",
    ].filter(Boolean);

    const body = chunks.join("\n\n");
    return `${bannerFrom}\n\n${importBlock(operations, body)}\n\n${body}\n`;
  }

  /** Only what this tag uses — a project may compile with `noUnusedLocals`. */
  function importBlock(operations: OperationInfo[], body: string) {
    const lines = [];
    const callers = [
      ...new Set(operations.map((item) => rt.callers[item.method])),
    ].sort();
    lines.push(`import { ${callers.join(", ")} } from "${rt.callers.module}";`);
    const usesList =
      list &&
      operations.some((operation) =>
        payloadFor(operation).startsWith(list.name),
      );
    const listWithTypes = usesList && list.module === rt.types.module;
    if (usesList && !listWithTypes) {
      lines.push(`import type { ${list.name} } from "${list.module}";`);
    }

    const usesQuery =
      hooks && operations.some((operation) => operation.method === "get");
    const usesMutation =
      hooks && operations.some((operation) => operation.method !== "get");
    // The hooks below are one line over the generic core — the query/mutation
    // wiring lives once in the hooks module, not once per operation.
    const usesInfinite = operations.some((operation) => infiniteOf(operation));
    const runtime = [
      ...(usesInfinite ? [rt.hooks.infinite] : []),
      ...(reactive && body.includes(`${rt.hooks.toValue}(`)
        ? [rt.hooks.toValue]
        : []),
      ...(usesQuery ? [rt.hooks.query] : []),
      ...(usesMutation ? [rt.hooks.mutation] : []),
    ];
    if (runtime.length) {
      lines.push(`import { ${runtime.join(", ")} } from "${rt.hooks.module}";`);
    }
    if (operations.some((operation) => operation.service)) {
      lines.push(`import { API_SERVICE_BASE_URLS } from "./services";`);
    }
    const types = [
      rt.types.request,
      ...(listWithTypes ? [list.name] : []),
      ...(usesInfinite ? [rt.types.infinite] : []),
      ...(usesQuery ? [rt.types.query] : []),
      ...(usesMutation ? [rt.types.mutation] : []),
      ...(reactive && body.includes(`${rt.types.maybeGetter}<`)
        ? [rt.types.maybeGetter]
        : []),
    ].sort();
    lines.push(
      `import type { ${types.join(", ")} } from "${rt.types.module}";`,
    );

    const available = new Set([
      ...Object.keys(registry()),
      ...extraModels.keys(),
    ]);
    // Comments and string literals are stripped first: a document's prose
    // mentioning "Road", or a tag named "Plate Lists", is not a use of a type.
    const code = body
      .replace(/^import[^\n]*$/gm, "")
      .replace(/\/\*[\s\S]*?\*\//g, "")
      .replace(/^\s*\/\/.*$/gm, "")
      .replace(/"(?:[^"\\\n]|\\.)*"/g, "")
      .replace(/'(?:[^'\\\n]|\\.)*'/g, "")
      .replace(/`(?:[^`\\]|\\.)*`/g, "");
    const used = [...available]
      .filter(
        (name) => /^[A-Z]/.test(name) && new RegExp(`\\b${name}\\b`).test(code),
      )
      .sort();
    if (used.length) {
      lines.push(`import type { ${used.join(", ")} } from "./models";`);
    }

    return lines.join("\n");
  }

  /**
   * `all` invalidates the whole tag; a key per read operation keeps its
   * arguments in the cache identity. The leaf before those arguments is the
   * operation's route, read from the tag's `Endpoints` map.
   */
  function keyFactoryBlock(tag: string, operations: OperationInfo[], keys: string, endpoints: string) {
    const reads = operations.filter((operation) => operation.method === "get");
    return [
      `/** Query keys for "${tag}". */`,
      `export const ${keys} = {`,
      `  all: [${JSON.stringify(tag)}] as const,`,
      `  lists: () => [...${keys}.all, "list"] as const,`,
      `  details: () => [...${keys}.all, "detail"] as const,`,
      ...reads.map((operation) => {
        const isDetail = operation.pathParams.length > 0;
        // What the answer depends on beside the route: a detail read that also
        // takes a query or headers keys on them too — two searches of the same
        // group, or the same read for two tenants, are two answers.
        const inputs = [
          ...(operation.queryParams.length
            ? [{ name: "params", type: queryTypeName(operation) }]
            : []),
          ...(operation.headerParams.length
            ? [{ name: "headers", type: headersTypeName(operation) }]
            : []),
        ];
        const args = [
          ...(isDetail
            ? operation.pathParams.map(
                (item) =>
                  `${identifier(item.name, `${operation.name}Path`)}: ${paramType(item)}`,
              )
            : []),
          ...inputs.map(
            (input) => `${input.name}${isDetail ? "?" : ""}: ${input.type}`,
          ),
        ].join(", ");
        const tail = [
          ...(isDetail ? pathArgNames(operation) : []),
          ...inputs.map((input) => input.name),
        ].join(", ");
        return [
          `  ${propertyName(operation.name)}: (${args}) =>`,
          `    [...${keys}.${isDetail ? "details()" : "lists()"}, ${endpointRef(endpoints, operation)}${tail ? `, ${tail}` : ""}] as const,`,
        ].join("\n");
      }),
      ...reads
        .filter((operation) => infiniteOf(operation))
        .map((operation) => infiniteKeyEntry(operation, keys, endpoints)),
      "} as const;",
    ].join("\n");
  }

  function queryTypeBlock(operation: OperationInfo) {
    if (!operation.queryParams.length) return "";
    return [
      `export type ${queryTypeName(operation)} = {`,
      ...operation.queryParams.map((item) =>
        [
          item.description ? `  /** ${oneLine(item.description)} */` : null,
          `  ${propertyName(item.name)}${item.required ? "" : "?"}: ${paramType(item)};`,
        ]
          .filter(Boolean)
          .join("\n"),
      ),
      "};",
    ].join("\n");
  }

  function headersTypeBlock(operation: OperationInfo) {
    if (!operation.headerParams.length) return "";
    return [
      `export type ${headersTypeName(operation)} = {`,
      ...operation.headerParams.map((item) =>
        [
          item.description ? `  /** ${oneLine(item.description)} */` : null,
          `  ${propertyName(item.name)}${item.required ? "" : "?"}: ${paramType(item)};`,
        ]
          .filter(Boolean)
          .join("\n"),
      ),
      "};",
    ].join("\n");
  }

  /** One object for a write, so a path id and a body are passed as one value. */
  function variablesBlock(operation: OperationInfo) {
    if (!hooks) return "";
    const parts = operation.pathParams.map(
      (item) =>
        `${identifier(item.name, `${operation.name}Path`)}: ${paramType(item)}`,
    );
    if (operation.queryParams.length) {
      const required = operation.queryParams.some((item) => item.required);
      parts.push(`query${required ? "" : "?"}: ${queryTypeName(operation)}`);
    }
    if (operation.headerParams.length) {
      parts.push(
        `headers${headersAreOptional(operation) ? "?" : ""}: ${headersTypeName(operation)}`,
      );
    }
    if (operation.bodySchema) {
      parts.push(
        `body${operation.bodyRequired ? "" : "?"}: ${bodyTypeName(operation)}`,
      );
    }
    if (!parts.length) return "";

    return `export type ${variablesTypeName(operation)} = {\n${parts
      .map((part) => `  ${part};`)
      .join("\n")}\n};`;
  }

  function requestBlock(operation: OperationInfo, endpoints: string) {
    const payload = payloadFor(operation);
    const caller = rt.callers[operation.method];
    const keys = rt.requestKeys;

    const args = operation.pathParams.map(
      (item) =>
        `${identifier(item.name, `${operation.name}Path`)}: ${paramType(item)}`,
    );
    if (operation.queryParams.length) {
      args.push(
        `query: ${queryTypeName(operation)}${queryIsOptional(operation) ? " = {}" : ""}`,
      );
    }
    if (operation.headerParams.length) {
      args.push(
        `headers: ${headersTypeName(operation)}${headersAreOptional(operation) ? " = {}" : ""}`,
      );
    }
    if (operation.bodySchema) {
      args.push(
        `body${operation.bodyRequired ? "" : "?"}: ${bodyTypeName(operation)}`,
      );
    }
    args.push(`config?: ${rt.types.request}<${payload}>`);

    const configLines = ["...config"];
    if (operation.queryParams.length) configLines.push(`${keys.query}: query`);
    if (operation.pathParams.length) {
      // The URL's `{user_id}` is replaced by the key it is written with, not
      // by the camelCased argument that carries the value.
      const entries = operation.pathParams.map((item, index) => {
        const argument = pathArgNames(operation)[index];
        return item.name === argument
          ? argument
          : `${propertyName(item.name)}: ${argument}`;
      });
      configLines.push(`${keys.pathParams}: { ${entries.join(", ")} }`);
    }
    // How the body goes out: multipart is a flag; any other body that is not
    // JSON names its `Content-Type`, and the client sends it accordingly.
    const kind = bodyKind(operation.bodyMediaType);
    const sendsForm = kind === "multipart" || (kind === "urlencoded" && !keys.headers);
    if (sendsForm) configLines.push(`${keys.formData}: true`);
    if (keys.headers) {
      const entries = [
        ...(operation.headerParams.length ? [headerSpread(operation)] : []),
        ...(kind === "urlencoded" || kind === "raw"
          ? [`"Content-Type": ${JSON.stringify(operation.bodyMediaType)}`]
          : []),
      ];
      if (entries.length) {
        configLines.push(
          `${keys.headers}: { ...config?.${keys.headers}, ${entries.join(", ")} }`,
        );
      }
    }
    if (keys.envelope && wrapsEnvelope(operation)) {
      configLines.push(`${keys.envelope}: true`);
    }
    // `apiDelete(route, config)` has no body argument, so a DELETE's body rides in the config.
    if (operation.method === "delete" && operation.bodySchema && keys.body) {
      configLines.push(`${keys.body}: body`);
    }
    if (operation.service) {
      configLines.push(
        `${keys.baseUrl}: config?.${keys.baseUrl} ?? API_SERVICE_BASE_URLS[${JSON.stringify(operation.service)}]`,
      );
    }

    // The route, not a copy of it — see `endpointRef`.
    const callArgs = [endpointRef(endpoints, operation)];
    if (["post", "put", "patch"].includes(operation.method)) {
      callArgs.push(operation.bodySchema ? "body" : "null");
    }
    callArgs.push(
      `{\n${configLines.map((line) => `    ${line}`).join(",\n")},\n  }`,
    );

    return [
      requestDoc(operation),
      `export function ${operation.name}(${args.join(", ")}) {`,
      `  return ${caller}<${payload}>(`,
      `    ${callArgs.join(",\n    ")},`,
      `  );`,
      `}`,
    ].join("\n");
  }

  function requestDoc(operation: OperationInfo) {
    const prose = [operation.summary, operation.description]
      .filter(Boolean)
      .map(oneLine)
      .filter(Boolean)
      .join(" — ");
    const lines = [
      prose || null,
      `\`${operation.method.toUpperCase()} ${operation.url}\``,
      operation.deprecated ? "@deprecated" : null,
    ].filter(Boolean);
    return `/**\n${lines.map((line) => ` * ${line}`).join("\n")}\n */`;
  }

  /** What a missing path argument is keyed as while its query is disabled. */
  function keyFallback(type: string) {
    if (type === "string") return '""';
    if (type === "number") return "0";
    if (type === "boolean") return "false";
    return "undefined as never";
  }

  function queryHookBlock(operation: OperationInfo, keys: string) {
    const payload = payloadFor(operation);
    const params = operation.pathParams.map(
      (item) =>
        `${identifier(item.name, `${operation.name}Path`)}: ${argType(`${paramType(item)} | undefined`)}`,
    );
    if (operation.queryParams.length) {
      params.push(
        `query: ${argType(queryTypeName(operation))}${queryIsOptional(operation) ? " = {}" : ""}`,
      );
    }
    if (operation.headerParams.length) {
      params.push(
        `headers: ${argType(headersTypeName(operation))}${headersAreOptional(operation) ? " = {}" : ""}`,
      );
    }
    // The key type is the factory's own return type: a wider `QueryKey` here
    // makes `enabled` and `placeholderData` unassignable.
    params.push(
      `options?: ${rt.types.query}<${payload}, ReturnType<typeof ${keys}.${operation.name}>>`,
    );

    const inputs = [
      ...(operation.queryParams.length ? [argRead("query")] : []),
      ...(operation.headerParams.length ? [argRead("headers")] : []),
    ];
    const keyArgs = [
      ...pathArgNames(operation).map(
        (item, index) =>
          `${argRead(item)} ?? ${keyFallback(paramType(operation.pathParams[index]))}`,
      ),
      ...inputs,
    ].join(", ");
    const callArgs = [
      ...pathArgNames(operation).map((item) => `${argRead(item)}!`),
      ...inputs,
    ];
    // A detail query waits for its id instead of requesting `/stations/undefined`.
    // The caller's `options` win, so it can still force `enabled`.
    const waiting = pathArgNames(operation);
    const guard = !waiting.length
      ? ""
      : reactive
        ? lazy(
            `[${waiting.map(argRead).join(", ")}].every((value) => value !== undefined && !Number.isNaN(value))`,
          )
        : waiting
            .map((item, index) =>
              paramType(operation.pathParams[index]) === "number"
                ? `${item} !== undefined && !Number.isNaN(${item})`
                : `${item} !== undefined`,
            )
            .join(" && ");
    const signal = rt.requestKeys.signal;
    const signalArg =
      signal === "signal" ? "{ signal }" : `{ ${signal}: signal }`;

    return [
      requestDoc(operation),
      `export function ${prefix}${pascalCase(operation.name)}Query(${params.join(", ")}) {`,
      `  return ${rt.hooks.query}(`,
      `    ${lazy(`${keys}.${operation.name}(${keyArgs})`)},`,
      `    (signal) => ${operation.name}(${callArgs.length ? `${callArgs.join(", ")}, ` : ""}${signalArg}),`,
      ...(reactive
        ? [`    options,`, ...(guard ? [`    ${guard},`] : [])]
        : guard
          ? [`    { enabled: ${guard}, ...options },`]
          : [`    options,`]),
      `  );`,
      `}`,
    ].join("\n");
  }

  function mutationHookBlock(operation: OperationInfo, keys: string) {
    const payload = payloadFor(operation);
    const hasVariables = Boolean(
      operation.pathParams.length ||
      operation.queryParams.length ||
      operation.headerParams.length ||
      operation.bodySchema,
    );
    const variablesType = hasVariables ? variablesTypeName(operation) : "void";
    const signal = rt.requestKeys.signal;
    const signalArg =
      signal === "signal" ? "{ signal }" : `{ ${signal}: signal }`;

    const lines = [
      requestDoc(operation),
      `export function ${prefix}${pascalCase(operation.name)}Mutation(`,
      `  options?: ${rt.types.mutation}<${payload}, ${variablesType}>,`,
      `) {`,
      `  return ${rt.hooks.mutation}(${keys}.all,`,
    ];

    if (!hasVariables) {
      lines.push(
        `    (_variables, signal) => ${operation.name}(${signalArg}),`,
      );
    } else {
      const slots = [...pathArgNames(operation)];
      const callArgs = [...pathArgNames(operation)];
      if (operation.queryParams.length) {
        slots.push("query");
        // A required query has no `{}` to fall back to.
        callArgs.push(queryIsOptional(operation) ? "query ?? {}" : "query");
      }
      if (operation.headerParams.length) {
        slots.push("headers");
        callArgs.push(headersAreOptional(operation) ? "headers ?? {}" : "headers");
      }
      if (operation.bodySchema) {
        slots.push("body");
        callArgs.push("body");
      }
      const renderedCallArgs = [...callArgs, signalArg].join(", ");
      lines.push(
        `    ({ ${slots.join(", ")} }, signal) =>`,
        `      ${operation.name}(${renderedCallArgs}),`,
      );
    }

    lines.push(`    options,`, `  );`, `}`);
    return lines.join("\n");
  }

  /**
   * Go services name schemas after their package (`handler.LoginBody`), which
   * is no TypeScript identifier. Such a schema is renamed to the name its
   * `$ref`s already resolve to (`HandlerLoginBody`), and every `$ref` follows.
   */
  function normalizeSchemaNames(doc: OpenApiDocument) {
    const schemas = doc.components?.schemas;
    if (!schemas) return doc;
    const renames = new Map();
    const taken = new Set(Object.keys(schemas));
    for (const name of Object.keys(schemas)) {
      let next = modelName(name);
      // A model must not shadow a global type the emitted code also uses.
      if (GLOBAL_TYPES.has(next)) next = `${next}Model`;
      if (next === name) continue;
      for (let i = 2; taken.has(next); i += 1) next = `${modelName(name)}${i}`;
      taken.add(next);
      renames.set(name, next);
    }
    if (!renames.size) return doc;
    const prefix = "#/components/schemas/";
    const text = JSON.stringify(doc, (key, value) =>
      key === "$ref" &&
      typeof value === "string" &&
      renames.has(value.slice(prefix.length))
        ? prefix + renames.get(value.slice(prefix.length))
        : value,
    );
    const next = JSON.parse(text);
    next.components.schemas = Object.fromEntries(
      Object.entries(next.components.schemas).map(([name, schema]) => [
        renames.get(name) ?? name,
        schema,
      ]),
    );
    return next;
  }

  // ── Assemble ──────────────────────────────────────────────────────────────

  spec = normalizeSchemaNames(upgradeDocument(spec));
  const operations = collectOperations();

  const byTag = new Map<string, OperationInfo[]>();
  for (const operation of operations) {
    for (const tag of operation.tags) {
      if (include.length && !include.includes(tag)) continue;
      if (exclude.includes(tag)) continue;
      if (!byTag.has(tag)) byTag.set(tag, []);
      byTag.get(tag)!.push(operation);
    }
  }

  // The tag modules re-render every operation's body, payload and parameter
  // types. Walking them now registers the inline objects those renderings
  // produce (a multipart body, an anonymous `data` object) before `models.ts`
  // is assembled — registered later, they would be missing from it.
  for (const tagOperations of byTag.values()) {
    for (const operation of tagOperations) {
      const at = `${operation.method.toUpperCase()} ${operation.path}`;
      where = `${at} response`;
      payloadFor(operation);
      if (operation.bodySchema) {
        where = `${at} request body`;
        bodyTypeName(operation);
      }
      for (const parameter of [
        ...operation.pathParams,
        ...operation.queryParams,
        ...operation.headerParams,
      ]) {
        where = `${at} parameter \`${parameter.name}\``;
        paramType(parameter);
        if (operation.queryParams.includes(parameter)) {
          checkQueryEncoding(parameter);
        }
      }
    }
  }

  const modelBlocks = new Map();
  const componentRefs = collectComponentRefs();
  let hasEnvelopeTypes = false;

  for (const name of Object.keys(registry())) {
    const schema = registry()[name];
    where = `schema ${name}`;

    // An `allOf` envelope uses the generic envelope type.
    const envelopePayload = envelopeDataPayload(schema, name);
    if (envelope && envelopePayload) {
      // Walk only the data property to register nested inline models, avoiding
      // the creation of Part1 types for the envelope structure itself.
      const [, narrowing] = schema.allOf ?? [];
      if (envelope && narrowing?.properties?.[envelope.data]) {
        typeFor(narrowing.properties[envelope.data], `${name}Data`);
      }

      const comment = schema?.description
        ? `/** ${oneLine(schema.description)} */\n`
        : "";
      modelBlocks.set(
        name,
        `${comment}export type ${name} = ${envelope.name}<${envelopePayload}>;`,
      );
      hasEnvelopeTypes = true;
      continue;
    }

    // A bare envelope is disposable only while nothing else names it: the
    // transport unwraps a response's, but an `allOf` part that $refs the base
    // still needs the base's type.
    if (
      isEnvelopeWrapper(schema) &&
      !componentRefs.has(`#/components/schemas/${name}`)
    ) {
      typeFor(schema, name); // still walk it, so nested inline models survive
      extraModels.delete(name);
      continue;
    }

    // Suppress EnvelopeBase if all envelopes now use the generic form.
    if (name === "EnvelopeBase" && isEnvelopeWrapper(schema)) {
      typeFor(schema, name);
      extraModels.delete(name);
      continue;
    }

    const rendered = typeFor(schema, name);
    // A named object schema is registered by `objectLiteral` itself; its body
    // is the type, otherwise `export type Station = Station` would alias
    // forever. `nullable` lands on the whole declaration — weaving it through
    // the body would emit `Message = Message | null`.
    const body = extraModels.get(name);
    const block = body
      ? `export type ${name} = ${body}${schema.nullable === true ? " | null" : ""};`
      : `export type ${name} = ${rendered};`;
    extraModels.delete(name);
    const comment = schema?.description
      ? `/** ${oneLine(schema.description)} */\n`
      : "";
    modelBlocks.set(name, `${comment}${block}`);
  }

  where = null;

  for (const [name, body] of extraModels) {
    if (!modelBlocks.has(name)) {
      modelBlocks.set(name, `export type ${name} = ${body ?? "unknown"};`);
    }
  }

  const files = new Map<string, string>();
  const modelsImport = envelope && hasEnvelopeTypes
    ? `import type { ${envelope.name} } from "${envelope.module}";\n\n`
    : "";
  files.set(
    "models.ts",
    `${bannerFrom}\n\n` +
      modelsImport +
      (modelBlocks.size
        ? shareIdenticalTypes(
            [...modelBlocks.values()],
            (a, b) => a.includes(b) || b.includes(a),
          ).join("\n\n")
        : "export {};") +
      "\n",
  );

  if (options.zod) {
    const zod = emitZod(spec, {
      banner: bannerFrom,
      // Envelopes are unwrapped by the transport; their payloads have validators.
      skip: (name) =>
        !modelBlocks.has(name) ||
        (envelope &&
          modelBlocks.get(name).includes(`= ${envelope.name}<`)),
    });
    if (zod) files.set("schemas.ts", zod);
  }

  const fileName = (tag: string) => options.transform.fileName?.(tag) ?? camelCase(tag);
  for (const [tag, tagOperations] of byTag) {
    files.set(`${fileName(tag)}.ts`, tagModule(tag, tagOperations));
  }

  // Every service the operations name — none when one document is built alone.
  const services = [
    ...new Set(
      [...byTag.values()].flatMap((items) =>
        items
          .map((operation) => operation.service)
          .filter((service): service is string => Boolean(service)),
      ),
    ),
  ].sort();
  if (services.length) {
    const urls = rt.services.baseUrls ?? {};
    const entry = (service: string): string => {
      if (rt.services.fn)
        return `${rt.services.fn}(${JSON.stringify(service)})`;
      return JSON.stringify(urls[service] ?? "");
    };
    files.set(
      "services.ts",
      [
        bannerPlain,
        ...(rt.services.fn
          ? [`import { ${rt.services.fn} } from "${rt.services.module}";`, ""]
          : []),
        rt.services.fn
          ? `/** Each backend service's base URL (see \`${rt.services.fn}\`). */`
          : "/** Each backend service's base URL. */",
        `export const API_SERVICE_BASE_URLS = {`,
        ...services.map(
          (service) => `  ${JSON.stringify(service)}: ${entry(service)},`,
        ),
        `} as const;`,
      ].join("\n") + "\n",
    );
  } else {
    files.set(
      "services.ts",
      [
        bannerPlain,
        "/** Each backend service's base URL. */",
        `export const API_SERVICE_BASE_URLS = {} as const;`,
      ].join("\n") + "\n",
    );
  }

  files.set(
    "index.ts",
    [
      bannerPlain,
      `export * from "./models";`,
      `export * from "./services";`,
      ...(files.has("schemas.ts") ? [`export * from "./schemas";`] : []),
      ...[...byTag.keys()]
        .sort()
        .map((tag) => `export * from "./${fileName(tag)}";`),
    ].join("\n") + "\n",
  );

  const count = [...byTag.values()].reduce(
    (total, items) => total + items.length,
    0,
  );
  return {
    files,
    operations: count,
    tags: byTag.size,
    problems: [...problems.values()],
  };
}
